import java.io.*;
import java.util.*;

public class Main {
    static class Line {
        long a, b;

        Line(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() {
            if (ptr >= len) {
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    len = 0;
                }
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++] & 0xff;
        }

        long nextLong() {
            int c;
            do {
                c = read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > 32) {
                val = val * 10 + (c - '0');
                c = read();
            }

            return val * sign;
        }

        int nextInt() {
            return (int) nextLong();
        }
    }

    static class Fenwick {
        int n;
        int[] tree;

        Fenwick(int n) {
            this.n = n;
            this.tree = new int[n + 1];
        }

        void add(int i, int delta) {
            while (i <= n) {
                tree[i] += delta;
                i += i & -i;
            }
        }

        int query(int i) {
            int sum = 0;
            while (i > 0) {
                sum += tree[i];
                i -= i & -i;
            }
            return sum;
        }
    }

    static int lowerBound(long[] arr, int len, long key) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < key) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    static long countLE(Line[] lines, long x) {
        return count(lines, x, false);
    }

    static long countLT(Line[] lines, long x) {
        return count(lines, x, true);
    }

    static long count(Line[] lines, long x, boolean strict) {
        int n = lines.length;
        long[] values = new long[n];

        for (int i = 0; i < n; i++) {
            values[i] = lines[i].a * x + lines[i].b;
        }

        long[] sorted = values.clone();
        Arrays.sort(sorted);

        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                sorted[m++] = sorted[i];
            }
        }

        Fenwick fw = new Fenwick(m);
        long answer = 0;

        for (int start = 0; start < n; ) {
            int end = start + 1;
            long slope = lines[start].a;

            while (end < n && lines[end].a == slope) {
                end++;
            }

            for (int i = start; i < end; i++) {
                int pos = lowerBound(sorted, m, values[i]) + 1;

                if (strict) {
                    answer += fw.query(pos - 1);
                } else {
                    answer += fw.query(pos);
                }
            }

            for (int i = start; i < end; i++) {
                int pos = lowerBound(sorted, m, values[i]) + 1;
                fw.add(pos, 1);
            }

            start = end;
        }

        return answer;
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        long x1 = fs.nextLong();
        long x2 = fs.nextLong();

        Line[] lines = new Line[n];

        for (int i = 0; i < n; i++) {
            long a = fs.nextLong();
            long b = fs.nextLong();
            lines[i] = new Line(a, b);
        }

        Arrays.sort(lines, (p, q) -> Long.compare(p.a, q.a));

        long answer = countLE(lines, x2) - countLT(lines, x1);

        System.out.println(answer);
    }
}
